import java.util.Scanner;

public class EmployeeManagementSystem {
    static final int MAX = 20;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Parallel Arrays for Employee Records
        int[] ids = new int[MAX];
        String[] names = new String[MAX];
        String[] depts = new String[MAX];
        double[] salaries = new double[MAX];
        int count = 0;

        // Pre-seed 3 sample employees
        ids[0] = 101; names[0] = "Alice Smith"; depts[0] = "IT"; salaries[0] = 60000.0;
        ids[1] = 102; names[1] = "Bob Jones"; depts[1] = "HR"; salaries[1] = 45000.0;
        ids[2] = 103; names[2] = "Charlie Davis"; depts[2] = "Sales"; salaries[2] = 52000.0;
        count = 3;

        boolean running = true;
        System.out.println("======================================================");
        System.out.println("      ENTERPRISE EMPLOYEE & PAYROLL SYSTEM            ");
        System.out.println("======================================================");

        while (running) {
            displayMenu();
            System.out.print("Select option (1-7): ");
            int choice = scanner.nextInt();
            scanner.nextLine(); // Clear newline buffer

            switch (choice) {
                case 1:
                    count = addEmployee(ids, names, depts, salaries, count, scanner);
                    break;
                case 2:
                    viewDirectory(ids, names, depts, salaries, count);
                    break;
                case 3:
                    searchEmployee(ids, names, depts, salaries, count, scanner);
                    break;
                case 4:
                    generatePayroll(ids, names, depts, salaries, count);
                    break;
                case 5:
                    viewAnalytics(ids, names, salaries, count);
                    break;
                case 6:
                    departmentSummary(depts, salaries, count);
                    break;
                case 7:
                    System.out.println("Exiting system. Have a great day!");
                    running = false;
                    break;
                default:
                    System.out.println("Invalid option. Please choose 1-7.");
            }
        }

        scanner.close();
    }

    public static void displayMenu() {
        System.out.println("\n--- MAIN MENU ---");
        System.out.println("1. Add New Employee");
        System.out.println("2. View All Employees (Directory)");
        System.out.println("3. Search Employee by ID or Name");
        System.out.println("4. Generate Monthly Payroll Report");
        System.out.println("5. View Salary Analytics (High/Low/Avg)");
        System.out.println("6. Department Expenditure Breakdown");
        System.out.println("7. Exit");
    }

    // TODO: Implement static methods for addEmployee, viewDirectory, searchEmployee, generatePayroll, viewAnalytics, departmentSummary
}

